defmodule Readability.MatchersTest do
  use ExUnit.Case, async: true

  import Bitwise
  alias Readability.Matchers, as: M

  # Generated by scripts/gen_matcher_cases.js: Readability.js's regexes run by Node over the
  # class/id strings and attribute values of the 130 test pages plus edge cases.
  @fixture Path.expand("../fixtures/matcher_cases.json", __DIR__)
  @external_resource @fixture

  setup_all do
    {:ok, cases: @fixture |> File.read!() |> :json.decode()}
  end

  defp nil_if_null(:null), do: nil
  defp nil_if_null(v), do: v

  # Returns the cases where `fun.(input)` differs from `expected`.
  defp mismatches(cases, fun) do
    for {input, expected} <- cases, (actual = fun.(input)) != expected, do: {input, expected, actual}
  end

  defp bit?(bits, b), do: (bits &&& b) != 0

  test "class/id keyword matchers agree with the JS regexes", %{cases: cases} do
    strings = cases["strings"]
    assert length(strings) > 10_000

    for {fun, b} <- [
          {&M.unlikely?/1, 1},
          {&M.maybe_candidate?/1, 2},
          {&M.positive?/1, 4},
          {&M.negative?/1, 8},
          {&M.byline?/1, 16},
          {&M.share_element?/1, 32},
          {&M.lazy_class?/1, 64}
        ] do
      assert mismatches(for([s, bits] <- strings, do: {s, bit?(bits, b)}), fun) == [], "#{inspect(fun)}"
    end
  end

  test "combined class + id predicates agree with JS on className + \" \" + id", %{cases: cases} do
    assert length(cases["pairs"]) > 1000

    for [class, id, bits, weight] <- cases["pairs"] do
      assert M.unlikely_candidate?(class, id) == bit?(bits, 1), inspect({class, id})
      assert M.byline?(class, id) == bit?(bits, 2), inspect({class, id})
      assert M.share_element?(class, id) == bit?(bits, 4), inspect({class, id})
      assert M.class_weight(class, id) == weight, inspect({class, id})
    end

    # one side empty: the combined predicates reduce to the single-string ones
    for [s, bits] <- cases["strings"] do
      unlikely = bit?(bits, 1) and not bit?(bits, 2)
      assert M.unlikely_candidate?(s, nil) == unlikely
      assert M.unlikely_candidate?(nil, s) == unlikely
      weight = if(bit?(bits, 8), do: -25, else: 0) + if(bit?(bits, 4), do: 25, else: 0)
      weight = if s == "", do: 0, else: weight
      assert M.class_weight(s, nil) == weight
      assert M.class_weight("", s) == weight
    end
  end

  test "image attribute patterns agree with JS", %{cases: cases} do
    image = cases["image_attrs"]
    assert mismatches(for([v, bits, _] <- image, do: {v, bit?(bits, 1)}), &M.image_ext?/1) == []
    assert mismatches(for([v, bits, _] <- image, do: {v, bit?(bits, 2)}), &M.lazy_srcset?/1) == []
    assert mismatches(for([v, bits, _] <- image, do: {v, bit?(bits, 4)}), &M.lazy_src?/1) == []

    b64 = fn v ->
      case M.b64_data_url(v) do
        {mime, rest} -> [binary_part(v, 0, byte_size(v) - byte_size(rest)), mime]
        nil -> :null
      end
    end

    assert mismatches(for([v, _, parts] <- image, do: {v, parts}), b64) == []
    assert Enum.count(image, fn [_, _, parts] -> parts != :null end) > 10
  end

  test "videos agrees with JS", %{cases: cases} do
    assert mismatches(for([v, e] <- cases["videos"], do: {v, e}), &M.video?(&1, nil)) == []
  end

  test "adWords / loadingWords agree with JS", %{cases: cases} do
    assert mismatches(for([t, e] <- cases["ad_loading"], do: {t, e}), &M.ad_or_loading_words?/1) == []
  end

  test "title separator regexes agree with JS", %{cases: cases} do
    sep = M.regex(:title_separator)

    for [title, bits, cut, first_removed, seps_removed] <- cases["titles"] do
      assert Regex.match?(sep, title) == bit?(bits, 1), inspect(title)
      assert Regex.match?(M.regex(:title_hierarchical_separator), title) == bit?(bits, 2), inspect(title)

      actual_cut =
        case Regex.scan(sep, title, return: :index) do
          [] -> :null
          matches -> binary_part(title, 0, matches |> List.last() |> hd() |> elem(0))
        end

      assert actual_cut == cut, inspect(title)
      assert Regex.replace(M.regex(:title_first_part), title, "") == first_removed, inspect(title)
      assert Regex.replace(sep, title, "") == seps_removed, inspect(title)
    end
  end

  test "meta property / name patterns agree with JS", %{cases: cases} do
    meta = cases["meta"]
    assert mismatches(for([v, p, _] <- meta, do: {v, nil_if_null(p)}), &M.meta_property_key/1) == []
    assert mismatches(for([v, _, n] <- meta, do: {v, nil_if_null(n)}), &M.meta_name_key/1) == []
  end

  test "JSON-LD patterns agree with JS", %{cases: cases} do
    assert mismatches(for([t, e] <- cases["jsonld_types"], do: {t, e}), &M.jsonld_article_type?/1) == []
    assert mismatches(for([s, e] <- cases["schema_org"], do: {s, e}), &M.schema_org?/1) == []
    assert mismatches(for([s, e] <- cases["cdata"], do: {s, e}), &M.strip_cdata/1) == []
  end

  test "hashUrl, sentence end and srcsetUrl agree with JS", %{cases: cases} do
    assert mismatches(for([s, e] <- cases["hash_url"], do: {s, e}), &Readability.Text.hash_url?/1) == []
    assert mismatches(for([s, e] <- cases["sentence_end"], do: {s, e}), &M.sentence_end?/1) == []

    srcset = &M.srcset_replace(&1, fn p1, p2, p3 -> ["[", p1, "]", p2 | p3] end)
    assert mismatches(for([s, e] <- cases["srcset"], do: {s, e}), srcset) == []
  end

  test "srcset_replace/2 follows the srcsetUrl regex's backtracking" do
    show = &M.srcset_replace(&1, fn p1, p2, p3 -> ["[", p1, "|", p2, "|", p3, "]"] end)
    assert show.("a 1x,b") == "[a| 1x|,][b||]"
    assert show.("a 1x b") == "a 1x [b||]"
    assert show.("a,b,c d") == "[a,b||,]c [d||]"
    assert show.(",,x 2w ,") == "[,,x| 2w| ,]"
    assert show.("a  \u00A0, b") == "[a||  \u00A0,] [b||]"
    assert show.("é.jpg 1.5x") == "[é.jpg| 1.5x|]"
    assert show.("a .x") == "[a| .x|]"
    assert show.("a 1xy") == "a [1xy||]"
    assert show.(", ") == "[,|| ]"
  end

  test "srcset_replace/2 is linear on a long run without a match" do
    for input <- [String.duplicate("a", 200_000) <> " b", String.duplicate("a,", 100_000) <> "a b"] do
      {us, _} = :timer.tc(fn -> M.srcset_replace(input, fn p1, p2, p3 -> [p1, p2 | p3] end) end)
      assert us < 200_000, "took #{us} µs"
    end
  end

  test "regex/1 compiles once and caches in :persistent_term" do
    assert %Regex{} = M.regex(:videos)
    assert [{{M, hash}, regexes}] = for({{M, _}, _} = entry <- :persistent_term.get(), do: entry)
    assert is_integer(hash) and Map.fetch!(regexes, :videos) == M.regex(:videos)
    assert_raise FunctionClauseError, fn -> apply(M, :regex, [:nope]) end
  end

  test "video?/2 uses a custom regex as given" do
    assert M.video?("https://example.com/v", Regex.compile!("example"))
    refute M.video?("https://example.com/v", nil)
  end
end
